class Solution {
    int gcd(int a, int b) {
        while (b) { int t = b; b = a % b; a = t; }
        return a;
    }
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        int ones = 0;
        for (int x : nums) if (x == 1) ones++;
        if (ones > 0) return n - ones;

        int minLen = INT_MAX;
        vector<pair<int,int>> states;

        for (int i = 0; i < n; i++) {
            vector<pair<int,int>> newStates;
            for (auto& [g, len] : states) {
                newStates.push_back({gcd(g, nums[i]), len + 1});
            }
            newStates.push_back({nums[i], 1});

            sort(newStates.begin(), newStates.end());
            states.clear();
            for (auto& [g, len] : newStates) {
                if (!states.empty() && states.back().first == g) {
                    states.back().second = min(states.back().second, len);
                } else {
                    states.push_back({g, len});
                }
            }

            if (!states.empty() && states[0].first == 1) {
                minLen = min(minLen, states[0].second);
            }
        }

        if (minLen == INT_MAX) return -1;
        return (minLen - 1) + (n - 1);
    }
};
